    'docs_faq_a2' => 'جی ہاں! FIS Real Estate ایک Progressive Web App (PWA) ہے۔ اسے اپنے آلے پر انسٹال کریں اور آف لائن کام جاری رکھیں۔ جب آپ دوبارہ انٹرنیٹ سے منسلک ہوں گے تو آپ کی تبدیلیاں خودکار طور پر سنک ہو جائیں گی۔',
    'docs_faq_a3' => 'آپ سے ماہانہ بلنگ آپ کے زیر انتظام یونٹس کی تعداد کو آپ کے ٹیئر ریٹ سے ضرب دے کر لی جاتی ہے۔ Basic %1$s TZS/یونٹ/ماہ ہے، Professional %2$s، اور Enterprise %3$s ہے۔ رعایتیں لاگو ہو سکتی ہیں۔',
