    'intro_go_tb' => 'ٹرائل بیلنس',
    'intro_go_aged' => 'واجبات کی عمر',
    'intro_properties_index_what' => 'ہر عمارت جو آپ سنبھالتے ہیں۔ پراپرٹی میں یونٹس ہوتے ہیں، اور باقی سب — کرایہ دار، لیز، کرایہ — انہی یونٹس سے جڑا ہے۔',
    'intro_properties_index_how' => 'نئے سسٹم میں یہیں سے شروع کریں۔ پراپرٹی شامل کریں، پھر اس کے یونٹس۔ یونٹس، تصاویر اور اخراجات دیکھنے کے لیے کسی بھی پراپرٹی پر کلک کریں۔',
    'intro_properties_create_what' => 'عمارت شامل کریں۔ صرف نام ضروری ہے — باقی بعد میں بھرا جا سکتا ہے۔',
    'intro_properties_create_how' => 'ایسا نام دیں جو لوگ رپورٹ میں پہچان سکیں۔ محفوظ کرنے کے بعد یونٹس شامل کریں۔',
    'intro_properties_view_what' => 'ایک پراپرٹی کے بارے میں سب کچھ: یونٹس، کتنے بھرے ہیں، تصاویر اور لاگت۔',
    'intro_properties_view_how' => 'یونٹس، تصاویر اور اخراجات کے درمیان جانے کے لیے ٹیبز استعمال کریں۔ لیز شروع اور ختم ہونے پر آکوپنسی خود اپ ڈیٹ ہوتی ہے۔',
    'intro_units_index_what' => 'آپ کی پراپرٹیز میں ہر کرائے کے قابل جگہ، اس کے کرائے اور آیا کوئی موجود ہے۔',
    'intro_units_index_how' => 'لیز بناتے ہی یونٹ خودبخود مشغول ہو جاتا ہے، اور لیز ختم ہونے پر خالی۔ کرایہ یہاں مقرر کریں — نئی لیز اسے ڈیفالٹ لیتی ہے۔',
    'intro_units_create_what' => 'پراپرٹی میں کرائے کے قابل جگہ شامل کریں — فلیٹ، کمرہ، دکان یا دفتر۔',
    'intro_units_create_how' => 'یہاں مقرر کردہ کرایہ اور کرنسی اس یونٹ پر لیز بناتے وقت ڈیفالٹ بن جاتے ہیں۔ حیثیت خالی رہنے دیں؛ لیز شروع ہوتے ہی خود بدل جاتی ہے۔',
    'intro_units_view_what' => 'ایک یونٹ: اس کی موجودہ لیز، کرایہ، تصاویر اور تاریخ۔',
    'intro_units_view_how' => 'اگر یونٹ مشغول دکھے مگر کوئی لیز نہ ہو، تو پرانی لیز آزاد کیے بغیر ہٹائی گئی — یونٹ کی حیثیت میں ترمیم کر کے درست کریں۔',
    'intro_tenants_index_what' => 'آپ سے کرایہ لینے والے سب، ماضی اور حال۔',
    'intro_tenants_index_how' => 'لیز پر رکھنے سے پہلے کرایہ دار درج کریں۔ لیز، ادائیگیاں، دستاویزات اور شناختی نقل دیکھنے کے لیے نام پر کلک کریں۔',
    'intro_tenants_create_what' => 'کسی کو درج کریں تاکہ اسے لیز پر رکھا جا سکے۔',
    'intro_tenants_create_how' => 'صرف نام اور فون ضروری ہیں۔ TIN، قریبی رشتہ دار اور ملازمت ابھی یا بعد میں شامل کریں — شناختی نقل محفوظ کرنے کے بعد کرایہ دار صفحے سے اپ لوڈ ہوتی ہے۔',
    'intro_tenants_view_what' => 'ایک کرایہ دار: اس کی لیز، ادائیگیاں، واجبات، دستاویزات اور شناخت۔',
    'intro_tenants_view_how' => 'دائیں طرف شناختی دستاویز کارڈ میں شناختی نقل اپ لوڈ کریں۔ باقی سب کے لیے — معاہدے، خط و کتابت، حوالہ جات — دستاویزات ٹیب استعمال کریں۔',
    'intro_tenants_edit_what' => 'کرایہ دار کی تفصیلات تبدیل کریں۔',
    'intro_tenants_edit_how' => 'شناختی نقل یہاں نہیں — یہ کرایہ دار کے اپنے صفحے سے سنبھالی جاتی ہے، کیونکہ یہ فائل ہے، فیلڈ نہیں۔',
    'intro_leases_index_what' => 'کرایہ دار کو یونٹ سے جوڑنے والا ہر معاہدہ، اس کے کرائے، مدت اور ادائیگی تعدد کے ساتھ۔',
    'intro_leases_index_how' => 'لیز ہی کرایہ وصولی شروع کرتی ہے۔ جب تک یونٹ پر فعال لیز نہ ہو، نہ بل بنتا ہے نہ واجبات دکھتے ہیں۔',
    'intro_leases_create_what' => 'طے شدہ شرائط پر کرایہ دار کو یونٹ میں رکھیں۔',
    'intro_leases_create_how' => 'فہرست میں صرف خالی یا محفوظ یونٹس دکھتے ہیں — یونٹ غائب ہو تو وہ پرانی لیز سے مشغول نشان زد ہے۔ کرایہ اور ڈپازٹ یونٹ سے بھرتے ہیں، اور ادائیگی تعدد طے کرتا ہے کہ کرایہ کتنی بار لگے گا۔',
    'intro_leases_view_what' => 'ایک لیز: اس کی شرائط، اس کے خلاف ادائیگیاں، اور دستاویزات۔',
    'intro_leases_view_how' => 'آغاز کی تاریخ سے ہر مدت میں کرایہ خودبخود لگتا ہے۔ دستخط کے قابل معاہدے کے لیے پرنٹ استعمال کریں۔',

    // Page introductions, money and ledger pages (part 35b)
    'intro_payments_index_what' => 'موصول ہونے والی ہر ادائیگی، اور ان کی رسیدیں۔',
    'intro_payments_index_how' => 'ادائیگی پہلے سب سے پرانے واجبات ادا کرتی ہے۔ جزوی ادائیگی پر باقی واجب رہتا ہے — جزوی ادائیگی کو صفر نہیں سمجھا جاتا۔',
    'intro_payments_create_what' => 'کرایہ دار سے موصول رقم درج کریں۔',
    'intro_payments_create_how' => 'ادائیگی کا طریقہ منتخب کریں: نقد اور چیک بینک میں جمع کرنے تک آپ کے پاس رہتے ہیں، جبکہ بینک ٹرانسفر سیدھے بینک جاتے ہیں۔ رقم خودبخود سب سے پرانے واجبات پر لگتی ہے۔',
    'intro_payments_view_what' => 'ایک ادائیگی: اس نے کیا ادا کیا، اس کی رسید، اور منسلک دستاویزات۔',
    'intro_payments_view_how' => 'ادائیگی الٹانے پر وہ واجبات دوبارہ کھل جاتے ہیں، اور کرایہ دار کے واجبات پہلے جیسے ہو جاتے ہیں۔',
    'intro_deposits_index_what' => 'آپ کے پاس رکھی سیکیورٹی ڈپازٹس، اور ان کے ساتھ کیا ہوا۔',
    'intro_deposits_index_how' => 'ڈپازٹ کرایہ دار کا مال ہے جب تک ضبط نہ ہو، اس لیے یہ کمایا نہیں بلکہ رکھا ہوا ہے۔ واپسی یا ضبطی کے لیے دوسرے شخص کی منظوری چاہیے۔',
    'intro_deposits_create_what' => 'لیز کے خلاف موصول ڈپازٹ درج کریں۔',
    'intro_deposits_create_how' => 'نقدی کرائے کی ادائیگی کی طرح آپ کے پاس آتی ہے۔ ڈپازٹ کرایہ دار کے لیے رکھی رقم کے طور پر درج ہوتی ہے، آمدنی نہیں۔',
    'intro_deposits_view_what' => 'ایک ڈپازٹ: کتنا رکھا ہے، کٹوتیاں، اور واپسی کی حیثیت۔',
    'intro_deposits_view_how' => 'واپسی سے پہلے کٹوتیاں تفصیل سے درج کریں۔ واپسی اور ضبطی فوراً نہیں ہوتیں، درخواست بناتی ہیں — کوئی اور کھاتہ، قابل ادائیگی کے تحت منظور کرتا ہے۔',
    'intro_expenses_index_what' => 'پراپرٹیز چلانے کا خرچ — بجلی، تنخواہیں، مرمت۔',
    'intro_expenses_index_how' => 'بل آتے ہی درج کریں، ادا ہوا ہو یا نہ ہوا۔ لاگت اسی مہینے میں شمار ہوتی ہے جس میں ہوئی، اور ادائیگی منظور ہونے تک واجب رہتی ہے۔',
    'intro_ledger_index_what' => 'آپ کی کھاتوں کی فہرست — بینک اکاؤنٹس، نقدی بکس، اور آمدنی و اخراجات کی اقسام جن کے خلاف سب درج ہوتا ہے۔',
    'intro_ledger_index_how' => 'ادائیگیاں درج کرنے سے پہلے یہ ترتیب دیں۔ بینک اکاؤنٹس شامل کریں، پھر ڈیفالٹ بینک منسلک کریں تاکہ ٹرانسفر کو منزل معلوم ہو۔ سسٹم نشان زد کھاتے خودکار بنتے ہیں اور حذف نہیں ہو سکتے۔',
    'intro_ledger_mappings_what' => 'خودکار اندراجات کہاں جاتے ہیں۔ ہر واقعہ — کرایہ، ڈپازٹ، بینک ٹرانسفر — ایک کھاتے کی طرف اشارہ کرتا ہے۔',
    'intro_ledger_mappings_how' => 'نمایاں قطاریں ابھی منسلک نہیں اور ان واقعات کے درج ہونے سے پہلے مقرر ہونی چاہئیں۔ نیچے کھاتے بند کرنے سے اس تاریخ یا اس سے پہلے کچھ درج نہیں ہوتا۔',
    'intro_ledger_charges_what' => 'کرایہ داروں کے واجبات: واجب الادا کرایہ، یوٹیلٹیز اور تاخیر فیس۔',
    'intro_ledger_charges_how' => 'ہر فعال لیز کے لیے ہر مدت میں چارجز خودبخود بنتے ہیں۔ اگر یہ خالی ہے تو روزانہ جنریٹر ابھی نہیں چلا — چارجز کے بغیر کوئی واجب نہیں۔',
    'intro_ledger_floats_what' => 'آپ کے لوگوں کے پاس کمپنی کی جانب سے رکھی نقدی، اور ان کے اعلان کردہ جمع۔',
    'intro_ledger_floats_how' => 'کوئی پہلی بار نقد ادائیگی درج کرے تو نقدی بیلنس خود بن جاتا ہے۔ رقم بینک پہنچنے پر بینک میں جمع کریں استعمال کریں — دوسرے شخص کی منظوری پر ہی بیلنس کم ہوتا ہے۔',
    'intro_ledger_payables_what' => 'ادائیگی یا منظوری کے منتظر سب کچھ: سپلائر بل، اور ساتھی کی مانگی ہوئی ڈپازٹ واپسی۔',
    'intro_ledger_payables_how' => 'منظوری سے ہی رقم اصل میں باہر جاتی ہے۔ آپ اپنی درخواست منظور نہیں کر سکتے، اس لیے کم از کم دو افراد کو منظوری کا اختیار چاہیے۔',
    'intro_ledger_journal_what' => 'کھاتوں میں ہر اندراج، چاہے کسی شخص نے کیا ہو یا سسٹم نے۔',
    'intro_ledger_journal_how' => 'منظوری کے منتظر اندراجات کچھ متاثر نہیں کرتے۔ پوسٹ شدہ اندراجات کبھی ترمیم نہیں ہوتے — غلطی الٹا کر درست کریں، دونوں ریکارڈ پر رہتے ہیں۔',
    'intro_ledger_create_what' => 'ہاتھ سے وہ درج کریں جو سسٹم خود نہیں نکال سکتا — ابتدائی بیلنس، درستی، یا ایڈجسٹمنٹ۔',
    'intro_ledger_create_how' => 'جمع کرنے سے پہلے ڈیبٹ اور کریڈٹ برابر ہونے چاہئیں، اور ہر سطر ایک ہی کرنسی کا کھاتہ استعمال کرے۔ پھر کوئی اور منظور کرتا ہے۔',
    'intro_ledger_view_what' => 'ایک اندراج، اس کی سطریں، اور کس نے بنایا اور منظور کیا۔',
    'intro_ledger_view_how' => 'پوسٹ شدہ اندراج ترمیم یا حذف نہیں ہو سکتا۔ آئینہ اندراج سے منسوخ کرنے کے لیے الٹ دیں استعمال کریں — اصل نظر آتا رہتا ہے، الٹا نشان زد۔',
    'intro_ledger_trial-balance_what' => 'صحت کی جانچ: کل ڈیبٹ بمقابلہ کل کریڈٹ، فی کرنسی۔',
    'intro_ledger_trial-balance_how' => 'یہ برابر ہونے چاہئیں۔ ہر اندراج محفوظ کرتے وقت جانچا جاتا ہے، تو فرق ہو تو کسی نے ایپلیکیشن سے باہر ڈیٹابیس بدلا ہے۔',
    'intro_ledger_statements_what' => 'نفع و نقصان، میزانیہ، فی یونٹ منافع، اور کون ادائیگی میں پیچھے ہے۔',
    'intro_ledger_statements_how' => 'ہر عدد ایک لنک ہے — کھاتے تک، پھر اس کے پیچھے اندراجات تک کلک کریں۔ آمدنی واجب ہونے پر اور اخراجات ہونے پر شمار ہوتے ہیں، نقدی حرکت پر نہیں۔',
    'intro_ledger_account_what' => 'ایک کھاتے پر ہر حرکت، رواں بیلنس کے ساتھ۔',
    'intro_ledger_account_how' => 'یہیں گوشوارے کا عدد سمجھایا جاتا ہے۔ ہر اندراج نمبر اس مکمل اندراج سے جڑتا ہے جہاں سے آیا۔',

