    'intro_properties_photos_what' => 'عمارت کی تصویریں — خالی جگہوں کے اشتہار اور حالت کے ریکارڈ کے لیے مفید۔',
    'intro_properties_photos_how' => 'یہاں کی تصویریں پوری جائیداد دکھاتی ہیں۔ کسی ایک فلیٹ کی تصویریں اسی یونٹ پر رکھیں۔',
    'intro_properties_settings_what' => 'صرف اسی جائیداد پر لاگو اصول، جیسے اس کا کرایہ چکر اور تاخیری فیس کی شرائط۔',
    'intro_properties_settings_how' => 'یہاں جو بھی طے ہو وہ صرف اس جائیداد کے لیے پورے نظام کی ترتیب پر غالب آتا ہے۔ عام اصول پر قائم رہنے کے لیے خانہ خالی چھوڑ دیں۔',
