    'intro_units_edit_how' => 'کرایہ بدلنے سے موجودہ معاہدے نہیں بدلتے — ان میں دستخط کے وقت طے شدہ رقم ہی رہتی ہے۔ جو وصول ہوتا ہے اسے بدلنے کے لیے معاہدے میں ہی کرایہ بدلیں۔',
    'intro_units_photos_what' => 'اس یونٹ کی تصویریں، اشتہار کے لیے اور اس کی حالت ریکارڈ کرنے کے لیے۔',
    'intro_units_photos_how' => 'یہ داخلے اور اخراج کے وقت لیں؛ ضمانت کے بارے میں زیادہ تر جھگڑے شروع ہونے سے پہلے ہی نمٹ جاتے ہیں۔',
    'intro_leases_edit_what' => 'موجودہ معاہدے کی شرائط بدلیں۔',
    'intro_leases_edit_how' => 'کرایہ یا وقفہ بدلنے کا اثر اب سے بننے والے واجبات پر پڑتا ہے۔ پہلے بن چکے واجبات اپنی اصل رقم رکھتے ہیں — غلط ہوں تو انہیں الٹا دیں۔',
