    'intro_payments_edit_what' => 'پہلے سے درج ادائیگی کی تفصیلات درست کریں۔',
    'intro_payments_edit_how' => 'ادائیگی مکمل ختم کرنے کے لیے اسے اس کے اپنے صفحے سے الٹائیں — اس سے وہ واجبات دوبارہ کھل جاتے ہیں جو اس نے چکائے تھے اور حسابات سے بھی وہ نکل جاتی ہے۔',
    'intro_payments_bulk_what' => 'ایک ساتھ کئی ادائیگیاں درج کریں، جب کرائے کے دن قطار لگ جائے۔',
    'intro_payments_bulk_how' => 'ہر سطر اس کرایہ دار کے سب سے پرانے بقایا واجبات پر لگتی ہے، بالکل ویسے ہی جیسے کوئی اکیلی ادائیگی لگتی۔',
    'intro_deposits_late-fees_what' => 'کرایہ وقت پر ادا نہ ہونے پر لگنے والی فیس۔',
    'intro_deposits_late-fees_how' => 'یہ آپ کے تاخیری فیس کے اصولوں کے مطابق روزانہ چلنے والے عمل سے خودبخود لگتی ہیں۔ وجہ درج کر کے فیس معاف کی جا سکتی ہے۔',
    'intro_deposits_late-fee-settings_what' => 'یہ اصول طے کرتے ہیں کہ تاخیری فیس کب لگے گی اور کتنی ہوگی۔',
    'intro_deposits_late-fee-settings_how' => 'مہلت کا وقت رکھیں تاکہ ایک دن دیر سے آئی ادائیگی پر جرمانہ نہ ہو، اور بالائی حد رکھیں تاکہ دیر سے چلے آ رہے کھاتے پر فیس بے قابو نہ ہو جائے۔',
    'intro_documents_index_what' => 'نظام میں محفوظ ہر فائل، اور ہر ایک کس چیز سے جڑی ہے۔',
    'intro_documents_index_how' => 'زمرے کے مطابق یا دستاویز جس سے جڑی ہے اس کے مطابق چھانٹیں۔ خفیہ نشان زد فائلوں پر نشان لگتا ہے، مگر یہ صفحہ کھول سکنے والے ہر شخص کو وہ نظر آتی ہیں۔',
    'intro_documents_upload_what' => 'فائل شامل کریں اور اسے جائیداد، یونٹ، کرایہ دار، معاہدے، ادائیگی، ضمانت یا خرچ سے جوڑیں۔',
    'intro_documents_upload_how' => 'کسی ریکارڈ سے یہاں آنے پر وہی پہلے سے منتخب ملتا ہے، اور صحیح جگہ فائل رکھنے کا یہی سب سے پکا طریقہ ہے۔',
    'intro_documents_view_what' => 'ایک دستاویز: جہاں ممکن ہو جھلک، اور وہ کس سے جڑی ہے۔',
    'intro_documents_view_how' => 'جو براؤزر نہ دکھا سکے اس کے لیے ڈاؤن لوڈ استعمال کریں۔ ترمیم ریکارڈ بدلتی ہے، فائل نہیں — فائل بدلنے کے لیے دوبارہ اپلوڈ کریں۔',
    'intro_inspections_index_what' => 'یونٹوں کی حالت کا معائنہ — داخلے، اخراج یا معمول کے مطابق۔',
    'intro_inspections_index_how' => 'اخراج کا معائنہ ہی ضمانت سے کٹوتی کو جائز ٹھہراتا ہے، اس لیے کوئی بھی ضمانت واپس کرنے سے پہلے یہ کر لیں۔',
    'intro_inspections_create_what' => 'کسی یونٹ کی حالت کا معائنہ شروع کریں۔',
    'intro_inspections_create_how' => 'تیار فہرست کے لیے کوئی سانچہ چنیں۔ جس چیز کے بعد میں پیسے مانگ سکتے ہوں اس کی تصویر ضرور لیں۔',
    'intro_inspections_view_what' => 'ایک معائنہ: جانچی گئی ہر شے، اس کی حالت اور اس کی تصویریں۔',
    'intro_inspections_view_how' => 'خراب نشان زد اشیاء کو ضمانت کی کٹوتی میں بدلا جا سکتا ہے، ان کی تفصیل اور تصویروں سمیت۔',
    'intro_inspections_move-out_what' => 'کرایہ دار کے جانے پر ہونے والا معائنہ، جس میں یونٹ کا موازنہ اُس حالت سے کیا جاتا ہے جس میں اُس نے اسے پایا تھا۔',
    'intro_inspections_move-out_how' => 'ضمانت واپس کرنے سے پہلے یہ مکمل کریں — اس کے بغیر کی گئی کٹوتیوں کا دفاع مشکل ہوتا ہے۔',
    'intro_inspections_deductions_what' => 'نقصان یا صفائی کے بدلے ضمانت سے روکی گئی رقم۔',
    'intro_inspections_deductions_how' => 'ہر کٹوتی کسی معائنے میں ملی بات پر مبنی ہونی چاہیے۔ کٹوتیوں کے بعد جو بچے وہی واپس کیا جاتا ہے۔',
    'intro_inspections_templates_what' => 'دوبارہ استعمال ہونے والی فہرستیں، تاکہ ہر معائنے میں وہی باتیں دیکھی جائیں۔',
    'intro_inspections_templates_how' => 'ہر قسم کی جائیداد کے لیے ایک بنائیں۔ ایک جیسی فہرست ہی دو معائنوں کا موازنہ ممکن بناتی ہے۔',
    'intro_maintenance_index_what' => 'مرمت اور دیکھ بھال کی درخواستیں، درج ہونے سے مکمل ہونے تک۔',
    'intro_maintenance_index_how' => 'کرایہ دار اپنے پورٹل سے یہ بھیج سکتے ہیں۔ ٹھیکیدار مقرر کریں، لاگت پر نظر رکھیں، اور کام مکمل ہونے پر یہ خرچ بن سکتی ہے۔',
    'intro_maintenance_create_what' => 'جو چیز ٹھیک ہونی ہے اسے درج کریں۔',
