    'intro_maintenance_view_what' => 'ایک درخواست: اس کی تاریخ، تصویریں، کس کو سونپی گئی اور کتنا خرچ ہوا۔',
    'intro_maintenance_view_how' => 'یہاں درج لاگت کو خرچ میں بدلا جا سکتا ہے، اور یہی اسے حسابات میں لاتا ہے۔',
    'intro_maintenance_edit_what' => 'دیکھ بھال کی درخواست کی تفصیلات بدلیں۔',
    'intro_maintenance_edit_how' => 'حالت بدلنا ہی کرایہ دار کو بتاتا ہے کہ کچھ ہو رہا ہے، بشرطیکہ اس نے پورٹل سے درخواست دی ہو۔',
