    'intro_maintenance_reports_what' => 'دیکھ بھال پر کتنا خرچ ہو رہا ہے — جائیداد، زمرے اور ٹھیکیدار کے حساب سے۔',
    'intro_maintenance_reports_how' => 'اس سے وہ عمارت پکڑی جاتی ہے جو ضرورت سے زیادہ خرچ کرا رہی ہو، یا وہ بار بار آنے والی خرابی جو ٹھیک ہونے کے بجائے بس ڈھانپی جا رہی ہو۔',
    'intro_utilities_index_what' => 'پانی، بجلی اور دیگر خدمات جن کا پیسہ کرایہ داروں سے وصول کیا جاتا ہے۔',
    'intro_utilities_index_how' => 'میٹر ریڈنگ درج کریں، اور آپ کے نرخ سے رقم نکل کر اُس کرایہ دار کے بقایا میں شامل ہو جاتی ہے۔',
    'intro_utilities_readings_what' => 'میٹر ریڈنگ، اور ان سے نکالے گئے واجبات۔',
    'intro_utilities_readings_how' => 'موجودہ ریڈنگ درج کریں؛ کھپت پچھلی بار سے فرق ہے۔ نئی کرایہ داری کی پہلی ریڈنگ غور سے جانچیں — اس کے بعد کا سب کچھ اسی پر ٹکا ہے۔',
    'intro_utilities_types_what' => 'جن خدمات کا بل بناتے ہیں، اور ہر ایک کا نرخ کیسے طے ہوتا ہے۔',
    'intro_utilities_types_how' => 'میٹر والی فراہمی کے لیے فی یونٹ چنیں، مقررہ ماہانہ خرچ کے لیے یکساں، اور جہاں کھپت کے ساتھ نرخ بدلے وہاں درجہ وار۔',
    'intro_vacancies_index_what' => 'وہ خالی یونٹ جن کا آپ اشتہار دے رہے ہیں، اور ان پر آنے والے استفسارات۔',
    'intro_vacancies_index_how' => 'صرف خالی یونٹ ہی فہرست میں آ سکتے ہیں۔ اس یونٹ پر معاہدہ بنتے ہی فہرست خودبخود بند ہو جاتی ہے۔',
    'intro_vacancies_create_what' => 'کسی خالی یونٹ کا اشتہار دیں۔',
    'intro_vacancies_create_how' => 'کرایہ اور تفصیل یونٹ سے آتے ہیں۔ تصویریں شامل کریں — بغیر تصویر کے اشتہار کو کہیں کم استفسارات ملتے ہیں۔',
    'intro_vacancies_view_what' => 'ایک اشتہار: وہ کیسا پڑھا جاتا ہے، اور کس نے اس کے بارے میں پوچھا ہے۔',
    'intro_vacancies_view_how' => 'اچھے لگنے والے استفسار کو کرایہ دار بنائیں، پھر معاہدہ — اس سے اشتہار خودبخود بند ہو جاتا ہے۔',
    'intro_vacancies_inquiries_what' => 'وہ لوگ جنہوں نے کسی خالی یونٹ کے بارے میں پوچھا ہے۔',
    'intro_vacancies_inquiries_how' => 'ہر ایک کو رابطہ ہو گیا یا بند نشان زد کریں تاکہ کسی کو دو بار نہ ٹوکا جائے اور کوئی بھول بھی نہ جائے۔',
    'intro_reports_index_what' => 'کارکردگی کی رپورٹیں — وصولی، بھراؤ اور بقایا۔',
    'intro_reports_index_how' => 'یہ آپ کے روزمرہ ریکارڈ پڑھتی ہیں۔ حسابات کے لیے اس کے بجائے لیجر کے گوشوارے دیکھیں۔',
    'intro_reports_financial_what' => 'ایک عرصے میں وصول اور خرچ ہونے والی رقم۔',
    'intro_reports_financial_how' => 'یہ نقدی کو اس کی حرکت کے وقت گنتی ہے۔ لیجر والا نفع و نقصان آمدنی کو تب گنتا ہے جب وہ واجب ہوئی، اس لیے دونوں الگ سوالوں کا جواب دیتے ہیں۔',
    'intro_reports_occupancy_what' => 'آپ کی کتنی جگہ کمائی کر رہی ہے، اور کتنی خالی پڑی ہے۔',
    'intro_reports_occupancy_how' => 'بھراؤ معاہدے کی حالت کے مطابق چلتا ہے، اس لیے وہ اتنا ہی درست ہے جتنے آپ کے معاہدے۔ معاہدہ ختم ہونے کے بعد بھی بھرا ہوا نشان زد یونٹ اس عدد کو بڑھا کر دکھائے گا۔',
    'intro_reports_custom_what' => 'اپنی پسند کے کالم اور چھلنیاں چن کر اپنی رپورٹ خود بنائیں۔',
    'intro_reports_custom_how' => 'جس پر دوبارہ کام کرنا ہو یا آگے بھیجنا ہو اسے اسپریڈشیٹ میں برآمد کریں۔',
    'intro_expenses_reports_what' => 'آپ نے کیا خرچ کیا، جائیداد اور زمرے کے حساب سے۔',
    'intro_expenses_reports_how' => 'لاگت اُسی مہینے میں گنی جاتی ہے جس میں وہ بنی، اس لیے دیر سے ادا ہوا بل بھی صحیح مہینے میں ہی آتا ہے۔',
    'intro_payments_gateway-transactions_what' => 'آن لائن گیٹ وے سے آنے والی ادائیگیاں۔',
    'intro_payments_gateway-transactions_how' => 'یہ خود درج ہوتی ہیں اور سیدھی بینک میں جاتی ہیں، کیونکہ نقدی کسی کے ہاتھ نہیں آئی۔ یہاں ناکام لین دین کا مطلب ہے کہ کرایہ دار سے پیسہ لیا ہی نہیں گیا۔',
    'intro_payments_gateway-settings_what' => 'آن لائن ادائیگی فراہم کرنے والا جوڑیں تاکہ کرایہ دار خود ادائیگی کر سکیں۔',
    'intro_payments_gateway-settings_how' => 'اعلان کرنے سے پہلے ایک چھوٹی اصلی ادائیگی سے جانچ لیں — غلط کنجی کرایہ دار کے سرے پر خاموشی سے ناکام ہوتی ہے۔',
    'intro_payments_gateway-pay_what' => 'آن لائن ادائیگی کرتے وقت کرایہ دار کو نظر آنے والا صفحہ۔',
    'intro_payments_gateway-pay_how' => 'یہ دیکھنے کے لیے اسے کھولیں کہ انہیں کیا نظر آئے گا۔ کامیاب ادائیگی خود درج ہو کر ان کے سب سے پرانے واجبات چکا دیتی ہے۔',
    'intro_settings_index_what' => 'کمپنی کی تفصیلات، کرنسی، ماڈیول اور پورے نظام کے اصول۔',
    'intro_settings_index_how' => 'ماڈیول ٹیب پوری سہولتیں چالو اور بند کرتا ہے۔ کچھ کے لیے اونچا منصوبہ درکار ہے، اور وہ نشان زد ہیں۔',
    'intro_settings_reminders_what' => 'خودکار پیغام جو کرایہ داروں کو بتاتے ہیں کہ کیا واجب ہے اور کیا بقایا۔',
    'intro_settings_reminders_how' => 'یاد دہانیاں وہی پڑھتی ہیں جو واقعی بقایا ہے، اس لیے ادا کر چکے کرایہ دار کو کبھی نہیں ٹوکا جاتا۔ چالو کرنے سے پہلے سانچہ اپنے اوپر آزمائیں۔',
    'intro_settings_backup_what' => 'اپنا ڈیٹا برآمد کریں، یا کسی دوسرے نظام سے لائیں۔',
    'intro_settings_backup_how' => 'کوئی بھی بڑا کام کرنے سے پہلے ایک نقل لے لیں — تھوک درآمد، ڈیٹا کی صفائی، یا ایسی تبدیلی جس پر بھروسہ نہ ہو۔',
    'intro_masters_users_what' => 'کون لاگ اِن کر سکتا ہے، اور ہر ایک کو کیا کرنے کی اجازت ہے۔',
    'intro_masters_users_how' => 'کم از کم دو لوگوں کو منظوری کا اختیار دیں — کوئی اپنا ہی کام منظور نہیں کر سکتا، اس لیے ایک ہی منظوری دینے والا ہو تو کچھ بھی کبھی منظور نہیں ہوگا۔',
    'intro_masters_roles_what' => 'اجازتوں کے گروہ جو طے کرتے ہیں کہ صارف کیا دیکھ اور بدل سکتا ہے۔',
    'intro_masters_roles_how' => 'ہر کردار کو اتنا ہی دیں جتنا ضروری ہو۔ جو نگران ادائیگی مٹا ہی نہ سکے وہ اسے غلطی سے بھی نہیں مٹائے گا۔',
    // Ledger documentation page (part 36)
    'docs_ledger_guide' => 'حسابی کھاتہ',
    'docs_led_intro' => 'پورے نظام کے پیچھے ایک مکمل دوہرے اندراج کا کھاتہ چلتا ہے۔ کرایہ، ادائیگیاں، ضمانتیں اور اخراجات خودبخود اس میں درج ہوتے چلے جاتے ہیں، اس لیے کسی کے ایک بھی اندراج لکھے بغیر آپ کے کھاتے درست رہتے ہیں۔',
    'docs_led_intro_note' => 'نظام چلانے کے لیے آپ کو دوہرے اندراج کا حساب سمجھنے کی ضرورت نہیں۔ ادائیگیاں اور اخراجات ویسے ہی درج کریں جیسے ہمیشہ کرتے آئے ہیں؛ کھاتہ اپنا خیال خود رکھتا ہے۔ یہ صفحہ بتاتا ہے کہ وہ کیا کر رہا ہے، اور وہ چند صفحے جہاں وہ آپ سے کچھ مانگتا ہے۔',
    'docs_led_ideas' => 'جاننے کے لائق تین باتیں',
    'docs_led_accrual' => 'کرایہ پہلے واجب ہوتا ہے، پھر ادا ہوتا ہے',
    'docs_led_accrual_desc' => 'ہر مدت میں ہر چالو معاہدے کے لیے ایک واجب بنتا ہے۔ یہی وہ لمحہ ہے جب کرایہ آمدنی بنتا ہے اور جب کرایہ دار پر قرض چڑھتا ہے — تب نہیں جب وہ پیسے دیتا ہے۔ پھر کوئی ادائیگی ایک یا زیادہ واجبات چکاتی ہے، سب سے پرانے سے شروع کر کے۔ اسی لیے بقایا بالکل درست رہتا ہے: جزوی ادائیگی قرض کو ٹھیک اتنا ہی گھٹاتی ہے جتنا ادا ہوا، اور ایک مہینے کی زائد ادائیگی اب اگلے مہینے کی کمی نہیں چھپا سکتی۔',
    'docs_led_float' => 'کسی کے ہاتھ میں پڑی نقدی پر نظر رہتی ہے',
    'docs_led_float_desc' => 'جب کوئی نقدی وصول کرتا ہے تو وہ سیدھی بینک نہیں جاتی — وہ کسی نقدی صندوق یا اس کی عارضی امانت میں جاتی ہے، یعنی کمپنی کی طرف سے رکھی گئی رقم۔ بینک میں جمع کرانے پر وہ ترسیل درج کرتا ہے۔ بقایا تبھی گھٹتا ہے جب کوئی منظوری دینے والا تصدیق کرے۔ کسی بھی وقت آپ دیکھ سکتے ہیں کہ کیا اور کہاں رکھا ہے۔',
    'docs_led_immutable' => 'درج شدہ اندراجات کبھی نہیں بدلتے',
    'docs_led_immutable_desc' => 'اندراج ایک بار درج ہو جانے کے بعد نہ اس میں ترمیم ہو سکتی ہے نہ وہ مٹایا جا سکتا ہے۔ غلطی الٹے اندراج سے درست کی جاتی ہے، جو اصل کو منسوخ کر دیتا ہے اور دونوں ریکارڈ میں رہتے ہیں۔ اسی لیے پچھلے مہینے چھپا ہوا گوشوارہ آج بھی سچ ہے۔',
    'docs_led_setup' => 'اسے تیار کرنا',
    'docs_led_setup_desc' => 'کھاتہ کچھ بھی درج کر سکے، اس سے پہلے چار کام، ایک ہی بار:',
    'docs_led_s1' => '1. دو لوگوں کو منظوری کا اختیار دیں',
    'docs_led_s1_desc' => 'ترتیبات &rsaquo; صارفین، "ادائیگیاں اور ضمانتیں منظور کر سکتے ہیں" پر نشان لگائیں۔ دو لوگ اگر آپ چاہتے ہیں کہ رقم باہر جانے پر دوسری نظر پڑے؛ ایک کافی ہے اگر آپ اکیلے نظام چلاتے ہیں اور خود منظوری چالو رکھتے ہیں۔',
    'docs_led_s2' => '2. اپنے کھاتے بنائیں',
    'docs_led_s2_desc' => 'کھاتہ &rsaquo; کھاتوں کی فہرست &rsaquo; نیا کھاتہ۔ ہر بینک کھاتہ شامل کریں (قسم: اثاثے، نوع: بینک کھاتہ)، کوئی بھی خردہ نقدی صندوق، اور وہ اخراجات کے کھاتے جن پر آپ رپورٹ چاہتے ہیں — بجلی، تنخواہیں، مرمت۔',
    'docs_led_s3' => '3. طے شدہ بینک جوڑیں',
    'docs_led_s3_desc' => 'کھاتہ &rsaquo; کھاتوں کا ربط۔ "طے شدہ بینک کھاتہ" والی سطر اس وقت تک نمایاں رہتی ہے جب تک آپ اسے مقرر نہ کریں۔ جب تک وہ کسی اصلی کھاتے کی طرف اشارہ نہ کرے، بینک منتقلیاں اور گیٹ وے ادائیگیاں درج نہیں ہو سکتیں۔',
    'docs_led_s4' => '4. واجبات بنانے والا عمل مقرر کریں',
    'docs_led_s4_desc' => 'ایک روزانہ کا عمل ہر معاہدے کا کرایہ واجب ہوتے ہی بنا دیتا ہے۔ اسے تاخیری فیس اور یاد دہانی کے کاموں سے پہلے چلنا چاہیے، کیونکہ وہ انہی واجبات کو پڑھتے ہیں۔ اس کے بغیر بقایا جم جاتا ہے اور کسی کو یاد نہیں دلایا جاتا۔',
    'docs_led_accounts' => 'کھاتوں کی فہرست',
    'docs_led_accounts_desc' => 'آپ جتنے چاہیں کھاتے بنا سکتے ہیں۔ کچھ آپ کے لیے بنا دیے جاتے ہیں اور ان پر نظام کا نشان ہوتا ہے — خودکار اندراجات انہی پر منحصر ہیں، اس لیے وہ مٹائے نہیں جا سکتے، اگرچہ ان کا نام بدلا جا سکتا ہے۔',
    'docs_led_a_asset' => 'اثاثے',
    'docs_led_a_asset_d' => 'بینک کھاتے، نقدی صندوق، عارضی امانتیں، اور جو کرایہ داروں پر واجب ہے',
    'docs_led_a_liab' => 'واجبات',
    'docs_led_a_liab_d' => 'کرایہ داروں کی طرف سے آپ کے پاس رکھی ضمانتیں، اور جو آپ پر سپلائرز کا واجب ہے',
    'docs_led_a_eq' => 'سرمایہ',
    'docs_led_a_eq_d' => 'ابتدائی بقایا اور جمع شدہ منافع',
    'docs_led_a_inc' => 'آمدنی',
    'docs_led_a_inc_d' => 'کرایہ، تاخیری فیس، وصول کی گئی خدمات، ضبط شدہ ضمانتیں',
    'docs_led_a_exp' => 'اخراجات',
    'docs_led_a_exp_d' => 'جس پر بھی آپ پیسہ خرچ کرتے ہیں؛ جتنوں پر رپورٹ چاہیے اتنے شامل کریں',
    'docs_led_kind_note' => '"نوع" کا خانہ سجاوٹ نہیں — یہ طے کرتا ہے کہ کھاتہ کہاں پیش ہوگا۔ نقدی بینک میں جمع کراتے وقت منزل کے طور پر صرف بینک کھاتہ نشان زد کھاتے دکھائی دیتے ہیں، اور کوئی خرچ ادا کرتے وقت ذریعہ صرف بینک یا نقدی کھاتے ہو سکتے ہیں۔ جو کھاتہ عام چھوڑا گیا ہو وہ صرف ہاتھ سے کیے اندراجات کے لیے دستیاب رہتا ہے۔',
